#!/usr/bin/env node
/**
 * Builds the Latin font subsets and the font licence notices (P5, Q2 = A).
 *   node scripts/subset-fonts.mjs          -> writes the generated files
 *   node scripts/subset-fonts.mjs --check  -> exits 1 if a committed file is stale
 *
 * Outputs (all generated, never edit by hand):
 *   src/modules/stylepacks/generated/fonts/<FaceId>.ts   one base64 subset per face
 *   src/modules/stylepacks/generated/fontLicenses.ts     OFL text + one notice per bundled family
 *   docs/licenses/FONTS.md                               the same notices, readable on GitHub
 *
 * Why base64 TypeScript modules instead of .ttf files: the editor WebView
 * receives fonts as base64 anyway (P1 fontFace.ts), and the GitHub tools
 * this project pushes with carry text only, so binary files can't be pushed.
 *
 * Steps per face:
 *  1. read the TTF from the pinned npm package and check its SHA-256
 *     against scripts/lib/fontSubset.js (refuse a changed upstream file),
 *  2. subset to SUBSET_RANGES with HarfBuzz (subset-font), output TrueType,
 *  3. parse the result's cmap and fail if any REQUIRED_TEXT character is missing,
 *  4. emit the module. HarfBuzz output is deterministic, so --check compares bytes.
 */
import { Buffer } from 'node:buffer';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import subsetFont from 'subset-font';

const require = createRequire(import.meta.url);
const { SUBSET_FACES, REQUIRED_TEXT, subsetText, FAMILY_PACKAGES, NEVER_SUBSET } = require('./lib/fontSubset.js');
const { cmapCodepoints } = require('./lib/ttfCmap.js');

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const sha256 = (b) => createHash('sha256').update(b).digest('hex');
const HEADER = (what) => `// GENERATED by scripts/subset-fonts.mjs. Do not edit. ${what}\n`;

/** Every file this run produces: path -> content. */
const outputs = new Map();

// --- 1-4: subsets -----------------------------------------------------------
const text = subsetText();
for (const face of SUBSET_FACES) {
  if (NEVER_SUBSET.includes(face.family)) throw new Error(`${face.family} has Reserved Font Names and must not be subset`);
  const srcPath = resolve(root, 'node_modules', face.source);
  const src = readFileSync(srcPath);
  const got = sha256(src);
  if (got !== face.sha256) {
    console.error(`Source changed for ${face.id}: expected ${face.sha256}, got ${got}. Re-check the licence, then update fontSubset.js.`);
    process.exit(1);
  }
  const out = Buffer.from(await subsetFont(src, text, { targetFormat: 'truetype' }));
  const have = cmapCodepoints(out);
  // Invariant: the subset keeps EVERY wanted character the original font has
  // (nothing the source could draw is lost). Characters the source never had
  // (Gaegu has no accented letters) fall back to the next CSS font, as before.
  const srcHave = cmapCodepoints(src);
  const lost = [...text].filter((ch) => srcHave.has(ch.codePointAt(0)) && !have.has(ch.codePointAt(0)));
  if (lost.length) {
    console.error(`${face.id} subset lost characters the source has: ${lost.join(' ')}`);
    process.exit(1);
  }
  // And the plain ASCII core must be there in every case.
  const missing = [...REQUIRED_TEXT].filter((ch) => ch.codePointAt(0) < 0x80 && !have.has(ch.codePointAt(0)));
  if (missing.length) {
    console.error(`${face.id} subset lacks ASCII characters: ${missing.join(' ')}`);
    process.exit(1);
  }
  const b64 = out.toString('base64');
  outputs.set(
    `src/modules/stylepacks/generated/fonts/${face.id}.ts`,
    HEADER(`Latin subset of ${face.family} (SIL OFL 1.1, no Reserved Font Name).`) +
      `// Source: ${face.source} (sha256 ${face.sha256})\n` +
      `// Subset: ${out.length} bytes, ${have.size} codepoints, sha256 ${sha256(out)}\n` +
      `export const FONT_BASE64 =\n  '${b64}';\n`,
  );
}

// --- licence notices --------------------------------------------------------
/** Splits a package's LICENSE_FONT into the copyright header and the OFL body. */
function splitLicence(txt) {
  const i = txt.indexOf('This Font Software is licensed');
  if (i < 0) throw new Error('not an OFL licence');
  return { copyright: txt.slice(0, i).trim(), body: txt.slice(i).trim() };
}
// Packages differ only in the FAQ link of the preamble (http/https scripts.sil.org/OFL or
// openfontlicense.org) and in whitespace; the licence terms are compared word for word.
const norm = (s) => s.replace(/https?:\/\/(scripts\.sil\.org\/OFL|openfontlicense\.org)\/?/g, '<OFL-URL>').replace(/\s+/g, ' ').trim();
let oflBody = null;
const notices = [];
for (const [family, pkg] of Object.entries(FAMILY_PACKAGES)) {
  const txt = readFileSync(resolve(root, 'node_modules/@expo-google-fonts', pkg, 'LICENSE_FONT'), 'utf8').replace(/\r\n/g, '\n');
  const { copyright, body } = splitLicence(txt);
  if (oflBody === null) oflBody = body;
  else if (norm(body) !== norm(oflBody)) {
    console.error(`${family}: licence body differs from the SIL OFL 1.1 text of the others; review it by hand.`);
    process.exit(1);
  }
  const reserved = /Reserved Font Name/i.test(copyright);
  if (reserved && !NEVER_SUBSET.includes(family)) {
    console.error(`${family} declares Reserved Font Names but is not in NEVER_SUBSET.`);
    process.exit(1);
  }
  notices.push({ family, copyright, reservedNames: reserved, modified: SUBSET_FACES.some((f) => f.family === family) });
}
outputs.set(
  'src/modules/stylepacks/generated/fontLicenses.ts',
  HEADER('Font licence notices shown in Me > Font licences.') +
    `export const OFL_TEXT = ${JSON.stringify(oflBody)};\n\n` +
    `export const FONT_NOTICES: readonly { family: string; copyright: string; reservedNames: boolean; modified: boolean }[] = ${JSON.stringify(notices, null, 2)};\n`,
);
outputs.set(
  'docs/licenses/FONTS.md',
  '<!-- GENERATED by scripts/subset-fonts.mjs. Do not edit. -->\n# Font licences\n\n' +
    'Every font NotedPo bundles is licensed under the SIL Open Font License 1.1 (full text below). ' +
    'Files come from the pinned @expo-google-fonts npm packages (package-lock.json). ' +
    'Faces marked "Latin subset" were reduced to Latin, Greek and common symbols by scripts/subset-fonts.mjs; ' +
    'they declare no Reserved Font Name, so they keep the family name (OFL condition 3). ' +
    'Families with Reserved Font Names ship unchanged.\n\n' +
    '| Family | Shipped as | Copyright |\n|---|---|---|\n' +
    notices
      .map((n) => `| ${n.family} | ${n.modified ? 'Latin subset' : 'unchanged'} | ${n.copyright.replace(/\s+/g, ' ').replace(/\|/g, '\\|')} |`)
      .join('\n') +
    '\n\n## SIL Open Font License 1.1\n\n```\n' +
    oflBody +
    '\n```\n',
);

// --- write or check ---------------------------------------------------------
let stale = 0;
for (const [rel, content] of outputs) {
  const abs = resolve(root, rel);
  const cur = existsSync(abs) ? readFileSync(abs, 'utf8') : null;
  if (cur === content) continue;
  if (check) {
    console.error(`Stale: ${rel} (run npm run build:fonts)`);
    stale++;
  } else {
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content);
    console.log(`Wrote ${rel} (${content.length} chars)`);
  }
}
if (check) {
  if (stale) process.exit(1);
  console.log(`Fonts OK: ${outputs.size} generated files are current.`);
}
